-- =====================================================================
-- FastTrack baseline schema.
--
-- Conventions:
--   * UUID primary keys, generated by the database (gen_random_uuid()).
--   * Every user-owned table carries user_id and is indexed on it; the
--     application layer additionally checks ownership (AuthorizationService).
--   * Enumerated values are TEXT + CHECK constraint, so values stay readable
--     in psql and a new value is a one-line migration (no PG type juggling).
--   * timestamptz everywhere. The app stores UTC.
-- =====================================================================

-- ---------------------------------------------------------------------
-- users
-- ---------------------------------------------------------------------
CREATE TABLE users (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email           TEXT        NOT NULL,
    display_name    TEXT        NOT NULL,
    picture_url     TEXT,
    -- Google's stable subject id. NULL for the demo user (no Google account).
    google_subject  TEXT,
    is_demo         BOOLEAN     NOT NULL DEFAULT FALSE,
    -- Demo sessions may read everything but may not mutate shared demo data.
    is_read_only    BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_login_at   TIMESTAMPTZ
);
CREATE UNIQUE INDEX ux_users_email          ON users (lower(email));
CREATE UNIQUE INDEX ux_users_google_subject ON users (google_subject) WHERE google_subject IS NOT NULL;

-- ---------------------------------------------------------------------
-- gmail_accounts - one connected mailbox per user.
-- The refresh token is stored AES-256-GCM encrypted (ciphertext + iv).
-- Access tokens are never persisted.
-- ---------------------------------------------------------------------
CREATE TABLE gmail_accounts (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id               UUID        NOT NULL UNIQUE REFERENCES users (id) ON DELETE CASCADE,
    email_address         TEXT        NOT NULL,
    refresh_token_cipher  BYTEA,
    refresh_token_iv      BYTEA,
    scopes                TEXT        NOT NULL,
    connected_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_sync_at          TIMESTAMPTZ,
    last_history_id       TEXT,
    sync_status           TEXT        NOT NULL DEFAULT 'IDLE',
    sync_error            TEXT,
    revoked_at            TIMESTAMPTZ,
    CONSTRAINT ck_gmail_sync_status CHECK (sync_status IN ('IDLE','RUNNING','ERROR','REVOKED'))
);

-- ---------------------------------------------------------------------
-- applications - one company + one position.
-- ---------------------------------------------------------------------
CREATE TABLE applications (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id              UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    company_name         TEXT        NOT NULL,
    company_normalized   TEXT        NOT NULL,
    position_title       TEXT        NOT NULL,
    position_normalized  TEXT        NOT NULL,
    requisition_id       TEXT,
    location             TEXT,
    ats_platform         TEXT,
    source               TEXT        NOT NULL DEFAULT 'MANUAL',
    status               TEXT        NOT NULL DEFAULT 'APPLIED',
    applied_at           TIMESTAMPTZ,
    first_response_at    TIMESTAMPTZ,
    last_event_at        TIMESTAMPTZ,
    needs_review         BOOLEAN     NOT NULL DEFAULT FALSE,
    needs_review_reason  TEXT,
    notes                TEXT,
    archived             BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_applications_source CHECK (source IN ('MANUAL','EMAIL','CSV_IMPORT','DEMO')),
    CONSTRAINT ck_applications_status CHECK (status IN (
        'APPLIED','APPLICATION_RECEIVED','UNDER_REVIEW',
        'ASSESSMENT_REQUESTED','ASSESSMENT_COMPLETED',
        'RECRUITER_CONTACT','INTERVIEW_REQUESTED','INTERVIEW_SCHEDULED',
        'INTERVIEW_COMPLETED','FINAL_ROUND',
        'OFFER_RECEIVED','OFFER_ACCEPTED','OFFER_DECLINED',
        'REJECTED','POSITION_CANCELLED','WITHDRAWN'))
);
CREATE INDEX ix_applications_user            ON applications (user_id);
CREATE INDEX ix_applications_user_status     ON applications (user_id, status);
CREATE INDEX ix_applications_user_company    ON applications (user_id, company_normalized);
CREATE INDEX ix_applications_needs_review    ON applications (user_id) WHERE needs_review;
-- Same requisition id at the same company is the same application (rule 1).
CREATE UNIQUE INDEX ux_applications_req
    ON applications (user_id, company_normalized, requisition_id)
    WHERE requisition_id IS NOT NULL;

-- ---------------------------------------------------------------------
-- email_messages - metadata only. Full bodies are never stored
-- (see docs/privacy.md): sender, subject, a short snippet and the
-- extracted fields are all that survive processing.
-- ---------------------------------------------------------------------
CREATE TABLE email_messages (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id           UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    gmail_message_id  TEXT        NOT NULL,
    gmail_thread_id   TEXT,
    sender_email      TEXT        NOT NULL,
    sender_name       TEXT,
    sender_domain     TEXT        NOT NULL,
    subject           TEXT        NOT NULL,
    snippet           TEXT        NOT NULL DEFAULT '',
    received_at       TIMESTAMPTZ NOT NULL,
    source            TEXT        NOT NULL DEFAULT 'GMAIL',
    -- Rule-based prefilter outcome, recorded for the "LLM calls avoided" metric.
    prefilter_result  TEXT        NOT NULL DEFAULT 'PENDING',
    prefilter_reason  TEXT,
    content_hash      TEXT        NOT NULL,
    application_id    UUID        REFERENCES applications (id) ON DELETE SET NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_email_source CHECK (source IN ('GMAIL','DEMO','TEST')),
    CONSTRAINT ck_email_prefilter CHECK (prefilter_result IN ('PENDING','KEPT','DROPPED'))
);
-- Idempotent sync: a Gmail message id is processed at most once per user.
CREATE UNIQUE INDEX ux_email_user_gmail_id ON email_messages (user_id, gmail_message_id);
CREATE INDEX ix_email_user_received   ON email_messages (user_id, received_at DESC);
CREATE INDEX ix_email_application     ON email_messages (application_id);
CREATE INDEX ix_email_content_hash    ON email_messages (content_hash);

-- ---------------------------------------------------------------------
-- email_classifications - the structured result for one email.
-- ---------------------------------------------------------------------
CREATE TABLE email_classifications (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email_id            UUID        NOT NULL UNIQUE REFERENCES email_messages (id) ON DELETE CASCADE,
    user_id             UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    category            TEXT        NOT NULL,
    company             TEXT,
    position_title      TEXT,
    requisition_id      TEXT,
    interview_datetime  TIMESTAMPTZ,
    assessment_deadline TIMESTAMPTZ,
    platform            TEXT,
    confidence          NUMERIC(4,3) NOT NULL DEFAULT 0,
    reason              TEXT,
    method              TEXT        NOT NULL,
    model               TEXT,
    prompt_version      TEXT,
    cache_hit           BOOLEAN     NOT NULL DEFAULT FALSE,
    latency_ms          INTEGER,
    needs_review        BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_classification_category CHECK (category IN (
        'APPLICATION_CONFIRMATION','REJECTION','ASSESSMENT_INVITE',
        'INTERVIEW_REQUEST','INTERVIEW_SCHEDULED','OFFER',
        'RECRUITER_OUTREACH','POSITION_CANCELLED','SURVEY_OR_ACCOUNT',
        'NOT_JOB_RELATED')),
    CONSTRAINT ck_classification_method CHECK (method IN ('LLM','RULE','MANUAL')),
    CONSTRAINT ck_classification_confidence CHECK (confidence >= 0 AND confidence <= 1)
);
CREATE INDEX ix_classification_user_category ON email_classifications (user_id, category);
CREATE INDEX ix_classification_review        ON email_classifications (user_id) WHERE needs_review;

-- ---------------------------------------------------------------------
-- email_corrections - a user disagreeing with the classifier.
-- This table is the source of the "live accuracy" metric.
-- ---------------------------------------------------------------------
CREATE TABLE email_corrections (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id            UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    email_id           UUID        NOT NULL REFERENCES email_messages (id) ON DELETE CASCADE,
    original_category  TEXT        NOT NULL,
    corrected_category TEXT        NOT NULL,
    original_company   TEXT,
    corrected_company  TEXT,
    original_position  TEXT,
    corrected_position TEXT,
    was_llm            BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ix_corrections_user ON email_corrections (user_id, created_at DESC);

-- ---------------------------------------------------------------------
-- application_events - append-only status history. Never updated.
-- ---------------------------------------------------------------------
CREATE TABLE application_events (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    application_id  UUID        NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
    user_id         UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    event_type      TEXT        NOT NULL,
    from_status     TEXT,
    to_status       TEXT,
    email_id        UUID        REFERENCES email_messages (id) ON DELETE SET NULL,
    actor           TEXT        NOT NULL DEFAULT 'SYSTEM',
    detail          TEXT,
    occurred_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_event_actor CHECK (actor IN ('SYSTEM','USER','EMAIL','IMPORT')),
    CONSTRAINT ck_event_type CHECK (event_type IN (
        'CREATED','STATUS_CHANGED','EMAIL_LINKED','NOTE_ADDED',
        'MERGED','SPLIT','EDITED','FLAGGED_FOR_REVIEW','REVIEW_RESOLVED'))
);
CREATE INDEX ix_events_application ON application_events (application_id, occurred_at);
CREATE INDEX ix_events_user        ON application_events (user_id, occurred_at DESC);

-- ---------------------------------------------------------------------
-- resumes - versioned. parsed_json holds the structured extraction.
-- ---------------------------------------------------------------------
CREATE TABLE resumes (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id        UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    version        INTEGER     NOT NULL,
    filename       TEXT        NOT NULL,
    size_bytes     INTEGER     NOT NULL,
    content_text   TEXT        NOT NULL,
    parsed_json    TEXT,
    parse_method   TEXT        NOT NULL DEFAULT 'PENDING',
    is_active      BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_resume_parse_method CHECK (parse_method IN ('PENDING','LLM','HEURISTIC','MANUAL'))
);
CREATE UNIQUE INDEX ux_resume_user_version ON resumes (user_id, version);
CREATE UNIQUE INDEX ux_resume_active       ON resumes (user_id) WHERE is_active;

-- ---------------------------------------------------------------------
-- job_postings - pasted text or fetched URL, plus the structured extraction.
-- ---------------------------------------------------------------------
CREATE TABLE job_postings (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    title         TEXT,
    company       TEXT,
    source_url    TEXT,
    source_type   TEXT        NOT NULL DEFAULT 'PASTED',
    raw_text      TEXT        NOT NULL,
    content_hash  TEXT        NOT NULL,
    parsed_json   TEXT,
    parse_method  TEXT        NOT NULL DEFAULT 'PENDING',
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_posting_source CHECK (source_type IN ('PASTED','URL')),
    CONSTRAINT ck_posting_parse_method CHECK (parse_method IN ('PENDING','LLM','HEURISTIC'))
);
CREATE INDEX ix_posting_user ON job_postings (user_id, created_at DESC);
CREATE INDEX ix_posting_hash ON job_postings (user_id, content_hash);

-- ---------------------------------------------------------------------
-- fit_checks - one scored resume x posting pair.
-- Component scores are stored so the total is always explainable.
-- ---------------------------------------------------------------------
CREATE TABLE fit_checks (
    id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id                UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    resume_id              UUID        NOT NULL REFERENCES resumes (id) ON DELETE CASCADE,
    job_posting_id         UUID        NOT NULL REFERENCES job_postings (id) ON DELETE CASCADE,
    application_id         UUID        REFERENCES applications (id) ON DELETE SET NULL,
    overall_score          INTEGER     NOT NULL,
    band                   TEXT        NOT NULL,
    required_coverage      NUMERIC(5,4) NOT NULL DEFAULT 0,
    preferred_coverage     NUMERIC(5,4) NOT NULL DEFAULT 0,
    experience_score       NUMERIC(5,4) NOT NULL DEFAULT 0,
    eligibility_score      NUMERIC(5,4) NOT NULL DEFAULT 0,
    ats_keyword_coverage   NUMERIC(5,4) NOT NULL DEFAULT 0,
    hard_mismatch          BOOLEAN     NOT NULL DEFAULT FALSE,
    scoring_version        TEXT        NOT NULL DEFAULT 'v1',
    details_json           TEXT        NOT NULL,
    created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_fit_band  CHECK (band IN ('STRONG','GOOD','STRETCH','LONG_SHOT')),
    CONSTRAINT ck_fit_score CHECK (overall_score BETWEEN 0 AND 100)
);
CREATE INDEX ix_fit_user        ON fit_checks (user_id, created_at DESC);
CREATE INDEX ix_fit_application ON fit_checks (application_id);

-- ---------------------------------------------------------------------
-- sync_runs - one Gmail sync. Gives sync throughput and prefilter numbers.
-- ---------------------------------------------------------------------
CREATE TABLE sync_runs (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id               UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    trigger_source        TEXT        NOT NULL,
    status                TEXT        NOT NULL DEFAULT 'RUNNING',
    started_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at           TIMESTAMPTZ,
    messages_fetched      INTEGER     NOT NULL DEFAULT 0,
    messages_new          INTEGER     NOT NULL DEFAULT 0,
    messages_dropped      INTEGER     NOT NULL DEFAULT 0,
    messages_classified   INTEGER     NOT NULL DEFAULT 0,
    llm_calls             INTEGER     NOT NULL DEFAULT 0,
    cache_hits            INTEGER     NOT NULL DEFAULT 0,
    applications_created  INTEGER     NOT NULL DEFAULT 0,
    applications_updated  INTEGER     NOT NULL DEFAULT 0,
    error_message         TEXT,
    CONSTRAINT ck_sync_trigger CHECK (trigger_source IN ('MANUAL','SCHEDULED','INITIAL')),
    CONSTRAINT ck_sync_status  CHECK (status IN ('RUNNING','SUCCESS','FAILED','SKIPPED'))
);
CREATE INDEX ix_sync_user ON sync_runs (user_id, started_at DESC);

-- ---------------------------------------------------------------------
-- llm_invocations - one row per call that actually left the process.
-- Powers the measured latency / cache-hit-rate numbers in RESULTS.md.
-- ---------------------------------------------------------------------
CREATE TABLE llm_invocations (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID        REFERENCES users (id) ON DELETE SET NULL,
    purpose         TEXT        NOT NULL,
    model           TEXT,
    prompt_version  TEXT,
    cache_hit       BOOLEAN     NOT NULL DEFAULT FALSE,
    success         BOOLEAN     NOT NULL DEFAULT TRUE,
    retried         BOOLEAN     NOT NULL DEFAULT FALSE,
    fell_back       BOOLEAN     NOT NULL DEFAULT FALSE,
    latency_ms      INTEGER     NOT NULL DEFAULT 0,
    prompt_tokens   INTEGER,
    completion_tokens INTEGER,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_llm_purpose CHECK (purpose IN ('CLASSIFY_EMAIL','PARSE_RESUME','PARSE_POSTING','RATE_EXPERIENCE'))
);
CREATE INDEX ix_llm_created ON llm_invocations (created_at DESC);
